 sd=S.loc[sid,'district'];distance=((S.latitude-S.loc[sid,'latitude'])**2+((S.longitude-S.loc[sid,'longitude'])*.628)**2)**.5
 for method in ['district','district_pol','city','near5','near10','near_district5']:
  mask=S.index!=sid
  if 'district' in method:mask=mask & (S.district==sd)
  if 'pol' in method:mask=mask & (POL==POL[sid])
  peers=S.index[mask]
  if method.startswith('near'):
   peers=distance.loc[peers].nsmallest(10 if method=='near10' else 5).index
  ref=Q[peers].apply(lambda x:x-x.mean()).mean(axis=1)
  y=Q[sid]
  cor={l:y.corr(ref.shift(l)) for l in range(-3,4)}
  best=max(cor,key=cor.get)
  rows.append(dict(sid=sid,method=method,corr=cor[0],bestlag=best,best=cor[best],gain=cor[best]-cor[0]))
a=pd.DataFrame(rows)
print(a.sort_values('gain',ascending=False).head(45).round(3).to_string(index=False))
